const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define two polygons representing northern and southern Cambodia.
  // Cambodia's bounding box is roughly [102.3, 10.3, 107.6, 14.7].
  // We'll split it at latitude 12.5.
  const northernCambodia = ee.Geometry.Polygon([
    [102.3, 12.5], [107.6, 12.5], [107.6, 14.7], [102.3, 14.7], [102.3, 12.5]
  ]);

  const southernCambodia = ee.Geometry.Polygon([
    [102.3, 10.3], [107.6, 10.3], [107.6, 12.5], [102.3, 12.5], [102.3, 10.3]
  ]);

  const startDate = '2016-08-01';
  const endDate = '2018-02-28';

  // 2. Data Acquisition & Check
  const fireCollection = ee.FeatureCollection('MODIS/061/MCD14DL')
    .filterDate(startDate, endDate);

  const collectionSize = fireCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No fire detections found for the period ${startDate} to ${endDate}.`);
    console.log('A');
    return;
  }
  console.log(`Total fire detections in timeframe: ${collectionSize}`);

  // 3. Processing & Calculation
  // Filter the fire detections for each region
  const northernFires = fireCollection.filterBounds(northernCambodia);
  const southernFires = fireCollection.filterBounds(southernCambodia);

  // Get the count of fire detections in each region
  const northernFireCount = northernFires.size().getInfo();
  const southernFireCount = southernFires.size().getInfo();

  // 4. Validation & Final Answer
  if (northernFireCount === null || southernFireCount === null) {
      console.log('Failed to calculate fire counts.');
      console.log('C3');
      return;
  }

  console.log(`Northern Cambodia fire detections: ${northernFireCount}`);
  console.log(`Southern Cambodia fire detections: ${southernFireCount}`);

  if (northernFireCount > southernFireCount) {
    console.log('A');
  } else {
    console.log('B');
  }
}

